@router.post("/api/v1/retention-jobs/{job_id}/pause")
def pause_retention_purge(
    job_id: str,
    scheduler: AsyncIOScheduler = Depends(get_scheduler),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    policy = db.query(RetentionScheduleRecord).filter(
        RetentionScheduleRecord.job_id == job_id,
        RetentionScheduleRecord.tenant_id == current_user.tenant_id
    ).first()
    if not policy or not current_user.is_compliance_officer:
        raise HTTPException(status_code=403, detail="Unauthorized to pause retention policy")
    job = scheduler.get_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Retention purge job not found")
    scheduler.pause_job(job_id)
    policy.is_paused = True
    db.commit()
    return {"status": "paused", "job_id": job_id}
